from typing import Optional

def find_solution(a: int, b: int, n: int) -> Optional[tuple]:
    # Check if a and b are coprime
    if gcd(a, b) != 1:
        return None

    # Extended Euclidean algorithm to find x and y
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        x = y1
        y = x1 - (x // y) * y1
        return gcd, x, y

    gcd, x, y = extended_gcd(a, b)

    # If gcd is not 1, no solution exists
    if gcd != 1:
        return None

    # Scale the solution to match the equation ax + by = n
    k = n // gcd
    return (k * x, k * y)

