def count_Occurrence(tup, lst):
    # Create a dictionary to store the count of each element in the list
    count_dict = {}

    # Iterate over each element in the list
    for element in lst:
        # If the element is already in the dictionary, increment its count
        if element in count_dict:
            count_dict[element] += 1
        # Otherwise, add the element to the dictionary with a count of 1
        else:
            count_dict[element] = 1

    # Create a new tuple to store the results
    result_tuple = ()

    # Iterate over each element in the tuple
    for element in tup:
        # If the element is in the dictionary, add its count to the result tuple
        if element in count_dict:
            result_tuple += (count_dict[element],)
        # Otherwise, add 0 to the result tuple
        else:
            result_tuple += (0,)

    return result_tuple

