def cal_sum(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 3
    elif n == 2:
        return 5

    # Initialize the first three Perrin numbers
    p0, p1, p2 = 3, 5, 8

    # Calculate the sum of the first n Perrin numbers
    total_sum = p0 + p1 + p2
    for i in range(3, n):
