def find_equal_tuple(Input):
    # Check if the input is a list of tuples
    if not isinstance(Input, list) or not all(isinstance(item, tuple) for item in Input):
        return False

    # Get the length of the first tuple
    first_tuple_length = len(Input[0])

    # Check if all tuples have the same length as the first tuple
    for tup in Input:
        if len(tup) != first_tuple_length:
            return False

    return True

