def check_min_heap_helper(arr, i):
    n = len(arr)

    # Base case: if i is a leaf node, it's a valid heap
    if 2 * i + 1 >= n:
        return True

    # Check if the current node is less than or equal to its children
    if arr[i] <= arr[2 * i + 1] and check_min_heap_helper(arr, 2 * i + 1):
        if 2 * i + 2 < n and arr[i] <= arr[2 * i + 2]:
            return check_min_heap_helper(arr, 2 * i + 2)

    return False

