def last(arr, x):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == x:
            result = mid
            left = mid + 1  # Move left to find the last occurrence
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return result

def left_rotate(n, d):
    # Ensure d is within the range of 0 to 31
    d = d % 32

    # Perform the left rotation
    return (n << d) | (n >> (32 - d))

