from sympy import isprime

def prime_fib(n: int) -> int:
    def fibonacci_generator():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    count = 0
    for fib_num in fibonacci_generator():
        if isprime(fib_num):
            count += 1
            if count == n:
                return fib_num

